ee:variables.ee:set-variable:
%dw 2.0
output application/json
var Elmendorf_subtotals=  vars."idp-response-data"."Elmendorf"."Subtotal" mapObject ((value, key, index) ->"Crude-SAR":value.GrossProduct )
var TSAR_subtotals= vars."idp-response-data"."TSAR"."Subtotal" mapObject ((value, key, index) -> (key):value.GrossProduct)
var Elmendorf_GrandTotal= vars."idp-response-data"."Elmendorf"."GrandTotal"."GrossProductTotal"
var SAR_GrandTotal= vars."idp-response-data"."TSAR"."GrandTotal"."GrossProductTotal"
---
TSAR_subtotals ++ Elmendorf_subtotals ++ 
{
    "SAR_GrandTotal": SAR_GrandTotal,
    "Elmendorf_GrandTotal": Elmendorf_GrandTotal

}

%dw 2.0
output application/json

---
{
    InventoryDate: vars."InventoryDate",
    Elmendorf_Products: (vars."aggregated-tis-data") - "SAR" - "Elmendorf" - "Crude-SAR",
    SAR_Products: {
       "Crude-SAR": vars."aggregated-tis-data"."Crude-SAR"
    },
    Elmendorf_GrandTotal: vars."aggregated-tis-data"."Elmendorf" ,
    SAR_GrandTotal: vars."aggregated-tis-data"."SAR"
}

%dw 2.0 output application/json var weekday= (vars."InventoryDate" as Date {format: "dd-MMM-yyyy"}) as String {format: "EEEE"}
--- { "Date": vars."InventoryDate", "weekday": weekday, "C1001": vars."tis-data"."Elmendorf_GrandTotal" default "0", //Crude - Elmendorf "C1002": vars."tis-data"."SAR_Products"."Crude-SAR" default "0", //Crude - Refinery "C1004": vars."tis-data"."Elmendorf_Products"."JET" default "0", "C1005": vars."tis-data"."Elmendorf_Products"."JET A" default "0", "C1006": vars."tis-data"."Elmendorf_Products"."KEROSENE" default "0", "C1007": vars."tis-data"."Elmendorf_Products"."JPTS" default "0", "C1008": vars."tis-data"."Elmendorf_Products"."ULSD/Conosol" default "0", "C1009": vars."tis-data"."Elmendorf_Products"."NHT-FEED" default "0", "C1010": vars."tis-data"."Elmendorf_Products"."ASU feed" default "0", "C1011": vars."tis-data"."Elmendorf_Products"."ULSD" default "0", "C1012": vars."tis-data"."Elmendorf_Products"."DHT FEED" default "0", "C1013": vars."tis-data"."Elmendorf_Products"."GASOLINE" default "0", "C1014": vars."tis-data"."Elmendorf_Products"."Ethanol" default "0", "C1015": vars."tis-data"."Elmendorf_Products"."FULL RANGE REF" default "0", "C1016": vars."tis-data"."Elmendorf_Products"."Premium PBOB" default "0", "C1017": vars."tis-data"."Elmendorf_Products"."Light Reformate" default "0", "C1018": vars."tis-data"."Elmendorf_Products"."ISOMERATE" default "0", "C1019": vars."tis-data"."Elmendorf_Products"."ATB" default "0", "C1020": vars."tis-data"."Elmendorf_Products"."LPG" default "0", "C1023": "0", // 1 BTMS "C1024": "0", // 1 TOPS "C1025": vars."tis-data"."Elmendorf_Products"."SLOP" default "0", "C1029": "0", // Includes DHT Feed/ LSD from Nixon "C1030": "0", // Includes Naphtha purchases "C1031": vars."idp-response-data"."TMS6"."RECEIPTS"."ETHANOL Receipts" default "0", // Include Ethanol purchases "C1032": "0", // Include Clear91 from 07/2020, and Toluene before 12/2019 "C1033": "0", // Include CBOB receipts "C1035": "0", // Biodiesel blended to ULSD "C1036": "0", // Toluene blended to Premium/87 Clear/87 Reg "C1037": -(vars."idp-response-data"."TMS6"."ETHANOL BASE") default "0", "C1038": vars."idp-response-data"."TMS6"."Premium" default "0", "C1039": vars."idp-response-data"."TMS6"."REFORMATE" default "0", "C1040": vars."idp-response-data"."TMS6"."CBOB" default "0", "C1041": vars."idp-response-data"."TMS6"."Gasoline Blendstock" default "0", "C1042": -((vars."idp-response-data"."TMS6"."REGULAR BASE" default "0") + (vars."idp-response-data"."TMS6"."ETHANOL BASE" default "0")) , "C1043": vars."idp-response-data"."TMS6"."JET-A BASE" default "0", "C1044": vars."idp-response-data"."TMS6"."KEROSENE BASE" default "0", "C1045": vars."idp-response-data"."TMS6"."JPTS BASE" default "0", "C1046": -(vars."idp-response-data"."TMS6"."#2 ULSD BASE") default "0", "C1047": -(vars."idp-response-data"."TMS6"."LPG MIX BASE") default "0", "C1048": vars."idp-response-data"."TMS6"."HSR/NAPHTHA BASE" default "0", "C1049": vars."idp-response-data"."TMS6"."LSR/NAPHTHA BASE" default "0", "C1050": -(vars."idp-response-data"."TMS6"."#4 OIL BASE") default "0", "C1051": vars."idp-response-data"."TMS6"."EXPORTS"."#2 ULSD BASE" default "0", "C1052": vars."idp-response-data"."TMS6"."DHT FEEDSTOCK" default "0", "C1058": "0", //Product to Elmendorf "C1060": "0", "C1061": "21364" // METER CONTROL
}
